import{_ as e,o as s,c as t,a0 as i}from"./chunks/framework.jwovEGr5.js";const u=JSON.parse('{"title":"Day 14: Data Race와 pthread Mutex","description":"","frontmatter":{},"headers":[],"relativePath":"outta-space/project/Day-14-Data-Race와-pthread-Mutex.md","filePath":"outta-space/project/Day-14-Data-Race와-pthread-Mutex.md"}'),n={name:"outta-space/project/Day-14-Data-Race와-pthread-Mutex.md"};function p(l,a,o,c,d,r){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="day-14-data-race와-pthread-mutex" tabindex="-1">Day 14: Data Race와 pthread Mutex <a class="header-anchor" href="#day-14-data-race와-pthread-mutex" aria-label="Permalink to &quot;Day 14: Data Race와 pthread Mutex&quot;">​</a></h1><p>여러 worker thread가 하나의 counter를 동시에 증가시켜 data race와 lost update를 재현하고, <code>pthread_mutex_t</code>로 critical section을 보호했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Worker 4개 × 1,000,000회 증가</span></span>
<span class="line"><span>Expected: 4,000,000</span></span></code></pre></div><p>Mutex가 없는 실행에서는 실제 결과가 <code>1,532,081</code>로 달라졌고, mutex 적용 후에는 <code>4,000,000</code>이 출력됐다.</p><h2 id="counter-와-lost-update" tabindex="-1">counter++와 lost update <a class="header-anchor" href="#counter-와-lost-update" aria-label="Permalink to &quot;counter++와 lost update&quot;">​</a></h2><p><code>counter++</code>는 C source에서는 한 문장이지만 개념적으로 read-modify-write 과정이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. counter 읽기</span></span>
<span class="line"><span>2. 1 더하기</span></span>
<span class="line"><span>3. counter에 저장</span></span></code></pre></div><p>두 thread의 실행이 겹치면 증가 결과가 사라질 수 있다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>counter = 10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Thread A: 10 읽기</span></span>
<span class="line"><span>Thread B: 10 읽기</span></span>
<span class="line"><span>Thread A: 11 저장</span></span>
<span class="line"><span>Thread B: 11 저장</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Expected: 12</span></span>
<span class="line"><span>Actual:   11</span></span></code></pre></div><p>여러 thread가 같은 memory location에 접근하고 하나 이상이 값을 변경하는데 synchronization이 없다면 data race가 발생한다. C에서 data race는 단순한 오차가 아니라 undefined behavior다.</p><p>결과가 한 번 우연히 <code>4,000,000</code>으로 나오더라도 코드가 안전하다는 증거가 되지 않는다.</p><h2 id="volatile은-해결책이-아니다" tabindex="-1">volatile은 해결책이 아니다 <a class="header-anchor" href="#volatile은-해결책이-아니다" aria-label="Permalink to &quot;volatile은 해결책이 아니다&quot;">​</a></h2><p><code>volatile</code>은 memory access가 compiler에 의해 함부로 제거되지 않도록 표현하는 데 사용한다. 그러나 다음 성질은 제공하지 않는다.</p><ul><li>Atomicity</li><li>Mutual exclusion</li><li>Thread 간 실행 순서</li><li>Memory synchronization</li></ul><p>따라서 shared counter에 <code>volatile</code>만 추가해도 data race는 해결되지 않는다.</p><h2 id="critical-section과-mutex" tabindex="-1">Critical section과 Mutex <a class="header-anchor" href="#critical-section과-mutex" aria-label="Permalink to &quot;Critical section과 Mutex&quot;">​</a></h2><p>동시에 실행되면 안 되는 shared-data 접근 영역을 critical section이라고 한다.</p><p>이번 코드에서는 <code>counter++</code>만 critical section이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pthread_mutex_lock()</span></span>
<span class="line"><span>→ counter++</span></span>
<span class="line"><span>→ pthread_mutex_unlock()</span></span></code></pre></div><p>한 thread가 mutex를 보유하는 동안 다른 thread는 같은 mutex를 획득할 수 있을 때까지 기다린다.</p><p>Mutex의 lifecycle은 다음 순서로 구성했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pthread_mutex_init() 한 번</span></span>
<span class="line"><span>→ worker thread 생성</span></span>
<span class="line"><span>→ worker가 lock / counter++ / unlock</span></span>
<span class="line"><span>→ 모든 worker pthread_join()</span></span>
<span class="line"><span>→ pthread_mutex_destroy() 한 번</span></span></code></pre></div><p>처음에는 <code>pthread_mutex_init()</code>을 thread 생성 반복문 안에 넣었다. 이미 초기화됐거나 사용 중인 mutex를 다시 초기화하는 것은 undefined behavior이므로 생성 반복문 앞으로 이동했다.</p><h2 id="default-mutex-attributes" tabindex="-1">Default mutex attributes <a class="header-anchor" href="#default-mutex-attributes" aria-label="Permalink to &quot;Default mutex attributes&quot;">​</a></h2><p>다음 호출은 기본 mutex attribute를 사용한다.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pthread_mutex_init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">mutex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>이번 실습에서는 같은 프로세스의 thread들이 사용하는 <code>PTHREAD_MUTEX_DEFAULT</code> mutex로 이해했다. Process-shared, robust, recursive, priority protocol 같은 특수 설정은 사용하지 않았다.</p><p>정적 초기화도 가능하다.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pthread_mutex_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mutex </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTHREAD_MUTEX_INITIALIZER;</span></span></code></pre></div><p>차이는 다음과 같다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PTHREAD_MUTEX_INITIALIZER</span></span>
<span class="line"><span>→ 선언 시 기본 mutex 정적 초기화</span></span>
<span class="line"><span>→ 별도 init 함수 호출과 반환값 없음</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pthread_mutex_init()</span></span>
<span class="line"><span>→ 실행 중 동적 초기화</span></span>
<span class="line"><span>→ 반환값 검사 가능</span></span>
<span class="line"><span>→ custom attribute 전달 가능</span></span></code></pre></div><h2 id="pthread-mutex의-error-handling" tabindex="-1">pthread mutex의 error handling <a class="header-anchor" href="#pthread-mutex의-error-handling" aria-label="Permalink to &quot;pthread mutex의 error handling&quot;">​</a></h2><p>Mutex 관련 pthread 함수는 성공 시 0, 실패 시 error number를 직접 반환한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>성공 → 0</span></span>
<span class="line"><span>실패 → error number</span></span></code></pre></div><p><code>errno</code>에 의존해 <code>perror()</code>를 호출하지 않고 반환값을 <code>strerror()</code>로 변환해야 한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>err = pthread_mutex_lock(...)</span></span>
<span class="line"><span>err != 0</span></span>
<span class="line"><span>→ fprintf(stderr, &quot;%s&quot;, strerror(err))</span></span></code></pre></div><p>Lock에 실패했다면 mutex를 획득하지 못했으므로 해당 경로에서 unlock하면 안 된다.</p><p>현재 실습 코드에는 <code>pthread_mutex_init()</code>, <code>lock()</code>, <code>unlock()</code>, <code>destroy()</code>의 반환값 검사를 추가하는 작업이 TODO로 남아 있다.</p><h2 id="mutex-destroy-시점" tabindex="-1">Mutex destroy 시점 <a class="header-anchor" href="#mutex-destroy-시점" aria-label="Permalink to &quot;Mutex destroy 시점&quot;">​</a></h2><p><code>pthread_mutex_destroy()</code>는 mutex를 사용할 thread가 더 이상 없을 때 호출해야 한다.</p><p>단순히 특정 순간 mutex가 unlocked인 것만으로는 충분하지 않다. 아직 실행 중인 worker가 이후 lock을 시도할 수 있기 때문이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>모든 worker join</span></span>
<span class="line"><span>→ mutex를 사용할 thread가 없음을 보장</span></span>
<span class="line"><span>→ mutex destroy</span></span></code></pre></div><p>Locked 상태이거나 다른 thread가 사용하거나 기다리는 mutex를 destroy하는 것은 undefined behavior다.</p><h2 id="실행-결과-비교" tabindex="-1">실행 결과 비교 <a class="header-anchor" href="#실행-결과-비교" aria-label="Permalink to &quot;실행 결과 비교&quot;">​</a></h2><p>Mutex 없는 버전:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>expected: 4000000</span></span>
<span class="line"><span>actual:   1532081</span></span></code></pre></div><p>Mutex 적용 버전:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>expected: 4000000</span></span>
<span class="line"><span>actual:   4000000</span></span></code></pre></div><p>Mutex 버전은 정확해졌지만 느려졌다. Counter 증가 4백만 회 각각에 lock과 unlock을 수행하고 여러 worker가 하나의 mutex를 두고 경쟁하기 때문이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>정확성 획득</span></span>
<span class="line"><span>↔ synchronization과 contention 비용 발생</span></span></code></pre></div><h2 id="threadsanitizer" tabindex="-1">ThreadSanitizer <a class="header-anchor" href="#threadsanitizer" aria-label="Permalink to &quot;ThreadSanitizer&quot;">​</a></h2><p>Data race를 동적으로 검출하기 위해 ThreadSanitizer를 사용했다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wextra</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wpedantic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -fsanitize=thread</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fno-omit-frame-pointer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pthread</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> race-demo-tsan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> race-demo.c</span></span></code></pre></div><p>현재 환경에서는 일반 실행 시 다음 오류가 발생했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FATAL: ThreadSanitizer: unexpected memory mapping</span></span></code></pre></div><p>TSan이 사용하는 shadow memory 영역과 실행 시 주소 배치가 충돌한 환경 문제였다. 해당 자식 프로세스에만 ASLR을 비활성화해 실행했다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setarch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x86_64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./race-demo-tsan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setarch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x86_64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./mutex-demo-tsan</span></span></code></pre></div><p>System-wide ASLR 설정은 변경하지 않았다.</p><p>Race 버전에서는 다음 정보가 보고됐다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WARNING: ThreadSanitizer: data race</span></span>
<span class="line"><span>Write by thread T1</span></span>
<span class="line"><span>Previous read/write by another thread</span></span>
<span class="line"><span>Location is global &#39;counter&#39;</span></span>
<span class="line"><span>race-demo.c의 counter++ line</span></span></code></pre></div><p>Mutex 버전에서는 같은 counter에 대한 data race warning이 나타나지 않았고 결과도 <code>4,000,000</code>이었다.</p><p>TSan은 실행 timing과 scheduling에 영향을 주므로 sanitizer 실행에서 나온 actual counter 숫자 자체보다 충돌한 memory location과 source line을 확인하는 것이 중요하다.</p><h2 id="futex와-fast-path" tabindex="-1">futex와 fast path <a class="header-anchor" href="#futex와-fast-path" aria-label="Permalink to &quot;futex와 fast path&quot;">​</a></h2><p>다음 명령으로 thread 생성, join과 mutex 경쟁을 관찰했다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trace=clone,clone3,futex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ./mutex-demo</span></span></code></pre></div><p>Lock과 unlock은 각각 4백만 번 호출했지만 <code>futex</code> system call은 그보다 훨씬 적었다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>경쟁 없음</span></span>
<span class="line"><span>→ user-space atomic operation으로 처리하는 fast path</span></span>
<span class="line"><span></span></span>
<span class="line"><span>실제 대기 필요</span></span>
<span class="line"><span>→ futex를 이용해 kernel에서 재우고 깨우는 slow path</span></span></code></pre></div><p>관찰된 <code>futex</code>가 모두 counter mutex에서 발생한 것은 아니다. <code>pthread_join()</code>도 worker 종료를 기다리기 위해 futex를 사용할 수 있다.</p><h2 id="linux-system-software-직무와의-연결" tabindex="-1">Linux System Software 직무와의 연결 <a class="header-anchor" href="#linux-system-software-직무와의-연결" aria-label="Permalink to &quot;Linux System Software 직무와의 연결&quot;">​</a></h2><p><code>sysmon-agent</code>에서는 collector thread가 shared metrics를 갱신하는 동안 network thread가 같은 metrics를 읽게 된다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Collector Thread ── write ──┐</span></span>
<span class="line"><span>                            ├─ Shared Metrics + Mutex</span></span>
<span class="line"><span>Network Thread ─── read ────┘</span></span></code></pre></div><p>Mutex가 없다면 network thread가 일부 field만 새 값인 불완전한 snapshot을 전송할 수 있다. Critical section의 범위와 mutex lifecycle을 올바르게 설계하는 능력이 필요하다.</p><h2 id="학습-정리" tabindex="-1">학습 정리 <a class="header-anchor" href="#학습-정리" aria-label="Permalink to &quot;학습 정리&quot;">​</a></h2><h3 id="learned" tabindex="-1">Learned <a class="header-anchor" href="#learned" aria-label="Permalink to &quot;Learned&quot;">​</a></h3><ul><li><code>counter++</code>는 atomic operation이 아니라 read-modify-write다.</li><li>Synchronization 없는 shared counter 접근은 data race이며 undefined behavior다.</li><li>실행 결과가 우연히 맞아도 thread-safe라는 뜻은 아니다.</li><li><code>volatile</code>은 atomicity나 thread synchronization을 제공하지 않는다.</li><li>Mutex로 critical section을 보호하면 lost update를 방지할 수 있다.</li><li>Mutex는 한 번 초기화하고 모든 worker를 join한 뒤 destroy해야 한다.</li><li>Mutex의 uncontended path는 user-space에서 처리될 수 있다.</li><li>실제 대기와 join에는 Linux의 <code>futex</code>가 사용될 수 있다.</li><li>ThreadSanitizer로 충돌한 thread, global variable과 source line을 찾을 수 있다.</li></ul><h3 id="apis" tabindex="-1">APIs <a class="header-anchor" href="#apis" aria-label="Permalink to &quot;APIs&quot;">​</a></h3><ul><li><code>pthread_mutex_init()</code></li><li><code>pthread_mutex_lock()</code></li><li><code>pthread_mutex_unlock()</code></li><li><code>pthread_mutex_destroy()</code></li><li><code>pthread_create()</code></li><li><code>pthread_join()</code></li></ul><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li><code>man 3posix pthread_mutex_init</code></li><li><code>man 3posix pthread_mutex_lock</code></li><li><code>gcc -pthread</code></li><li><code>gcc -fsanitize=thread</code></li><li><code>setarch x86_64 -R</code></li><li><code>strace -f -c -e trace=clone,clone3,futex</code></li></ul><h3 id="mistakes" tabindex="-1">Mistakes <a class="header-anchor" href="#mistakes" aria-label="Permalink to &quot;Mistakes&quot;">​</a></h3><ul><li><code>pthread_mutex_init()</code>을 worker 생성 반복문 안에 넣어 같은 mutex를 여러 번 초기화했다.</li><li>처음에는 pthread 함수 반환값을 <code>(void)err</code>로 버려 compiler warning만 숨겼다.</li><li>정상 출력만으로 concurrency code의 안전성을 판단할 수 있다고 생각할 수 있었다.</li><li>TSan의 <code>unexpected memory mapping</code>을 처음에는 코드의 data race 진단으로 오해할 수 있었다.</li></ul><h3 id="todo" tabindex="-1">TODO <a class="header-anchor" href="#todo" aria-label="Permalink to &quot;TODO&quot;">​</a></h3><ul><li>불필요한 <code>&lt;threads.h&gt;</code> header를 제거한다.</li><li>Mutex init, lock, unlock, destroy의 반환값을 모두 검사한다.</li><li>Thread 생성이 일부만 성공했을 때 실패 상태를 반환한다.</li><li>Join 하나가 실패해도 나머지 생성된 thread의 회수를 계속 시도한다.</li><li>고정 숫자를 thread count 상수로 통일한다.</li></ul><h3 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h3><ul><li>Socket의 endpoint와 file descriptor 개념을 학습한다.</li><li>Blocking TCP echo server와 client를 구현한다.</li><li>이후 <code>/proc</code> collector와 <code>sysmon-agent</code>로 연결한다.</li></ul>`,85)])])}const k=e(n,[["render",p]]);export{u as __pageData,k as default};
